class Solution:

	def countSubstring(self, S):
		n = len(S)
		dp = [0] * (2 * n + 1)
		(minius, count) = (0, n)
		for i in range(n):
			if S[i] == '0':
				count -= 1
			else:
				count += 1
			if count <= n:
				minius += 1
			dp[count] += 1
		ans = 0
		ind = n
		for i in range(n):
			ans += n - i - minius
			if S[i] == '1':
				ind += 1
				dp[ind] -= 1
				minius += dp[ind]
			else:
				minius -= 1
				minius -= dp[ind]
				ind -= 1
				dp[ind] -= 1
		return ans
